bool loadWav15(const std::wstring&p,std::vector<int16_t>&out){std::ifstream f(p,std::ios::binary);if(!f)return false;char id[4];uint32_t n=0;f.read(id,4);f.read((char*)&n,4);f.read(id,4);if(!f||std::string(id,4)!="WAVE")return false;uint16_t fmt=0,ch=0,bits=0;uint32_t rate=0;std::vector<char> data;while(f.read(id,4)){uint32_t sz=0;f.read((char*)&sz,4);if(!f)break;if(std::string(id,4)=="fmt "){uint16_t al=0;uint32_t br=0;f.read((char*)&fmt,2);f.read((char*)&ch,2);f.read((char*)&rate,4);f.read((char*)&br,4);f.read((char*)&al,2);f.read((char*)&bits,2);if(sz>16)f.seekg(sz-16,std::ios::cur);}else if(std::string(id,4)=="data"){data.resize(sz);f.read(data.data(),sz);}else f.seekg(sz,std::ios::cur);if(sz&1)f.seekg(1,std::ios::cur);}if(fmt!=1||bits!=16||(ch!=1&&ch!=2)||rate!=SR||data.empty())return false;const int16_t*s=(const int16_t*)data.data();size_t frames=data.size()/(2*ch);out.resize(frames*2);for(size_t i=0;i<frames;i++){int16_t a=s[i*ch],b=ch==2?s[i*ch+1]:a;out[i*2]=a;out[i*2+1]=b;}return true;}
void mixSample15(std::vector<int16_t>&a,int startBar){double secBar=240.0/std::max(60,bpm);long long bf=(long long)(secBar*SR);for(int l=0;l<(int)lanes.size();l++){auto&s=samples15[l];if(s.bar<0||s.pcm.empty()||lanes[l].mute)continue;long long dst=((long long)s.bar-startBar)*bf;if(dst<0)continue;double g=lanes[l].volume/100.0;for(size_t k=0;k+1<s.pcm.size();k+=2){size_t j=(size_t)(dst+(long long)k/2)*2;if(j+1>=a.size())break;for(int c=0;c<2;c++)a[j+c]=(int16_t)std::clamp((int)a[j+c]+(int)(s.pcm[k+c]*g),-32768,32767);}}}
void mixBoom15(std::vector<int16_t>&a,int startBar){double secBar=240.0/std::max(60,bpm);long long bf=(long long)(secBar*SR),sf=bf/STEPS;for(int l=0;l<(int)lanes.size();l++){if(!kicks15[l].enabled||lanes[l].mute||lanes[l].type!=LaneType::Drums)continue;auto&k=kicks15[l];for(int b=startBar;b<activeBars;b++){auto&d=drumForLane11(l,b);for(int s=0;s<STEPS;s++)if(d[0][s]){long long st=((long long)b-startBar)*bf+(long long)s*sf,len=std::min<long long>((long long)(SR*(0.055+k.decay*0.0032)),sf);double ph=0;for(long long q=0;q<len;q++){double t=(double)q/SR;double env=std::exp(-t*(13.0+(100-k.decay)*0.11));double hz=38.0+k.pitch*0.95+(95.0*k.punch/100.0)*std::exp(-t*42.0);ph+=6.283185307179586*hz/SR;double body=std::sin(ph)*env*(0.48+0.20*k.punch/100.0);double click=(q<(long long)(SR*0.0025))?(1.0-(double)q/(SR*0.0025))*0.12*k.punch/100.0:0.0;double drv=1.0+k.drive/35.0;double x=std::tanh((body+click)*drv)/std::tanh(drv);size_t j=(size_t)(st+q)*2;if(j+1>=a.size())break;int add=(int)(x*10500.0*lanes[l].volume/100.0);for(int c=0;c<2;c++)a[j+c]=(int16_t)std::clamp((int)a[j+c]+add,-32768,32767);}}}}}
void masterBus15(std::vector<int16_t>&a){double outGain=std::clamp(master,0,100)/100.0;if(!masterOn15){for(auto&v:a)v=(int16_t)std::lrint(v*outGain);return;}double env=0;for(auto&v:a){double x=v/32768.0;env=std::max(std::abs(x),env*0.9993);double cg=env>0.55?std::pow(0.55/env,0.30):1.0;x*=cg*1.12;x=std::tanh(x*1.08)/std::tanh(1.08);x*=outGain;v=(int16_t)std::lrint(std::clamp(x,-0.94,0.94)*32767.0);}}
void render15(std::vector<int16_t>&a,int start){renderRange11(a,start);mixSample15(a,start);mixBoom15(a,start);masterBus15(a);}
void play15(){if(playing){stopAudio();return;}playStartBar=cursorBar;render15(playBuffer,playStartBar);WAVEFORMATEX f{};f.wFormatTag=WAVE_FORMAT_PCM;f.nChannels=2;f.nSamplesPerSec=SR;f.wBitsPerSample=16;f.nBlockAlign=4;f.nAvgBytesPerSec=SR*4;if(waveOutOpen(&wave,WAVE_MAPPER,&f,(DWORD_PTR)win,0,CALLBACK_WINDOW)!=MMSYSERR_NOERROR){wave=nullptr;return;}waveHdr={};waveHdr.lpData=(LPSTR)playBuffer.data();waveHdr.dwBufferLength=(DWORD)std::min<size_t>(playBuffer.size()*2,0xFFFFFFFFu);waveOutPrepareHeader(wave,&waveHdr,sizeof(waveHdr));waveOutWrite(wave,&waveHdr,sizeof(waveHdr));playing=true;SetTimer(win,1,33,nullptr);InvalidateRect(win,nullptr,FALSE);}
void export15(){auto p=dialog(true,L"WAV Audio\0*.wav\0",L"wav");if(p.empty())return;std::vector<int16_t>a;render15(a,0);std::ofstream o(p,std::ios::binary);uint32_t ds=(uint32_t)(a.size()*2),rs=36+ds,fs=16,rate=SR,br=SR*4;uint16_t pcm=1,ch=2,al=4,bits=16;o.write("RIFF",4);o.write((char*)&rs,4);o.write("WAVEfmt ",8);o.write((char*)&fs,4);o.write((char*)&pcm,2);o.write((char*)&ch,2);o.write((char*)&rate,4);o.write((char*)&br,4);o.write((char*)&al,2);o.write((char*)&bits,2);o.write("data",4);o.write((char*)&ds,4);o.write((char*)a.data(),ds);}
std::wstring editText15(HWND owner,const std::wstring&initial){HINSTANCE hi=(HINSTANCE)GetWindowLongPtrW(owner,GWLP_HINSTANCE);static std::wstring result;result=initial;static HWND ed=nullptr;static bool reg=false;if(!reg){WNDCLASSW wc{};wc.hInstance=hi;wc.lpszClassName=L"BoomifyRename15";wc.lpfnWndProc=[](HWND h,UINT m,WPARAM w,LPARAM l)->LRESULT{if(m==WM_CREATE){ed=CreateWindowW(L"EDIT",result.c_str(),WS_CHILD|WS_VISIBLE|WS_BORDER|ES_AUTOHSCROLL,14,14,280,26,h,(HMENU)1,nullptr,nullptr);CreateWindowW(L"BUTTON",L"OK",WS_CHILD|WS_VISIBLE,218,48,76,26,h,(HMENU)2,nullptr,nullptr);SetFocus(ed);SendMessageW(ed,EM_SETSEL,0,-1);return 0;}if(m==WM_COMMAND&&LOWORD(w)==2){wchar_t b[128]{};GetWindowTextW(ed,b,128);result=b;DestroyWindow(h);return 0;}if(m==WM_CLOSE){result.clear();DestroyWindow(h);return 0;}return DefWindowProcW(h,m,w,l);};RegisterClassW(&wc);reg=true;}HWND q=CreateWindowExW(WS_EX_TOPMOST,L"BoomifyRename15",L"Renommer la piste",WS_POPUP|WS_CAPTION|WS_SYSMENU,CW_USEDEFAULT,CW_USEDEFAULT,325,115,owner,nullptr,hi,nullptr);EnableWindow(owner,FALSE);ShowWindow(q,SW_SHOW);MSG msg{};while(IsWindow(q)&&GetMessageW(&msg,nullptr,0,0)>0){TranslateMessage(&msg);DispatchMessageW(&msg);}EnableWindow(owner,TRUE);SetForegroundWindow(owner);return result;}
void renameLane15(int l){if(l<0||l>=(int)lanes.size())return;auto s=editText15(win,lanes[l].name);if(!s.empty())lanes[l].name=s;InvalidateRect(win,nullptr,FALSE);}
