void importSample15(){if(laneSelected<0||laneSelected>=(int)lanes.size()||lanes[laneSelected].type!=LaneType::Audio){MessageBoxW(win,L"Ajoute ou selectionne une piste AUDIO.",L"Boomify Sample",MB_OK);return;}auto p=dialog(false,L"WAV PCM 16-bit 44.1 kHz\0*.wav\0",L"wav");if(p.empty())return;std::vector<int16_t> pcm;if(!loadWav15(p,pcm)){MessageBoxW(win,L"WAV PCM 16-bit 44.1 kHz requis pour cette Alpha.",L"Boomify",MB_OK);return;}samples15[laneSelected]={p,selectedBar,std::move(pcm)};InvalidateRect(win,nullptr,FALSE);}
void addBoom15(){if((int)lanes.size()>=V6_MAX_TRACKS)return;lanes.push_back({L"BoomBox Kick",LaneType::Drums,false,false,82});laneSelected=(int)lanes.size()-1;kicks15[laneSelected].enabled=true;colors15[laneSelected]=RGB(225,88,62);layoutV6(win);InvalidateRect(win,nullptr,FALSE);}
